import type { FastifyInstance, FastifyReply } from "fastify";
import {
  BookmarkCreateSchema,
  BookmarkIdParamsSchema,
  BookmarkListQuerySchema,
  type BookmarkCreate,
  type BookmarkIdParams,
  type BookmarkListQuery,
} from "../../shared/contracts/api.js";
import { AddressValidationError } from "../../shared/types/address.js";
import {
  BookmarkNotFoundError,
  BookmarkRepository,
  DuplicateBookmarkError,
} from "../repositories/bookmark-repository.js";
import { IconRepository } from "../repositories/icon-repository.js";
import {
  fallbackTitleFromAddress,
  normalizeAddress,
} from "../services/bookmarks/address-normalizer.js";

export interface MetadataQueue {
  enqueue(bookmarkId: number, address: string, addressRevision: number): void;
}

function sendAddressProblem(reply: FastifyReply, error: AddressValidationError) {
  return reply.code(422).send({ code: error.code, message: error.message, field: error.field });
}

function sendDuplicate(reply: FastifyReply, error: DuplicateBookmarkError) {
  return reply.code(409).send({
    code: "DUPLICATE_BOOKMARK",
    message: "That address is already saved. Open the existing bookmark to edit it.",
    field: "address",
    existingBookmarkId: error.identity.id,
    existingScope: error.identity.archived ? "archived" : "active",
  });
}

export async function registerBookmarkRoutes(app: FastifyInstance, metadataQueue?: MetadataQueue) {
  const bookmarks = new BookmarkRepository(app.database);
  const icons = new IconRepository(app.database);

  app.post<{ Body: BookmarkCreate }>(
    "/api/bookmarks",
    { schema: { body: BookmarkCreateSchema } },
    async (request, reply) => {
      try {
        const normalized = normalizeAddress(request.body.address);
        const bookmark = bookmarks.create({
          input: request.body,
          address: normalized.address,
          normalizedAddress: normalized.normalizedAddress,
          fallbackTitle: fallbackTitleFromAddress(normalized.address),
          now: app.now().toISOString(),
        });
        const row = bookmarks.getRow(bookmark.id);
        if (row) metadataQueue?.enqueue(bookmark.id, bookmark.address, row.address_revision);
        return reply.code(201).send(bookmark);
      } catch (error) {
        if (error instanceof AddressValidationError) return sendAddressProblem(reply, error);
        if (error instanceof DuplicateBookmarkError) return sendDuplicate(reply, error);
        throw error;
      }
    },
  );

  app.get<{ Querystring: BookmarkListQuery }>(
    "/api/bookmarks",
    { schema: { querystring: BookmarkListQuerySchema } },
    async (request) => bookmarks.listActive(request.query.limit),
  );

  app.get<{ Params: BookmarkIdParams }>(
    "/api/bookmarks/:bookmarkId",
    { schema: { params: BookmarkIdParamsSchema } },
    async (request, reply) => {
      try {
        return bookmarks.get(request.params.bookmarkId);
      } catch (error) {
        if (error instanceof BookmarkNotFoundError) {
          return reply.code(404).send({ code: "BOOKMARK_NOT_FOUND", message: error.message });
        }
        throw error;
      }
    },
  );

  app.get<{ Params: BookmarkIdParams }>(
    "/api/bookmarks/:bookmarkId/icon",
    { schema: { params: BookmarkIdParamsSchema } },
    async (request, reply) => {
      const bytes = icons.getForBookmark(request.params.bookmarkId);
      if (!bytes) return reply.code(404).send();
      return reply
        .header("Content-Type", "image/png")
        .header("X-Content-Type-Options", "nosniff")
        .header("Cache-Control", "public, max-age=31536000, immutable")
        .send(bytes);
    },
  );
}
import type { FastifyInstance, FastifyReply } from "fastify";
import {
  type MetadataPreview,
  type MetadataPreviewRequest,
  MetadataPreviewRequestSchema,
} from "../../shared/contracts/api.js";
import { AddressValidationError } from "../../shared/types/address.js";
import { BookmarkRepository } from "../repositories/bookmark-repository.js";
import {
  fallbackTitleFromAddress,
  normalizeAddress,
} from "../services/bookmarks/address-normalizer.js";

export interface MetadataPreviewer {
  preview(address: string): Promise<MetadataPreview>;
}

function fallbackPreview(address: string): MetadataPreview {
  const title = fallbackTitleFromAddress(address);
  return {
    address,
    status: "pending",
    fallbackTitle: title,
    title,
    description: "",
    iconAvailable: false,
    errorCode: null,
  };
}

function addressProblem(reply: FastifyReply, error: AddressValidationError) {
  return reply.code(422).send({ code: error.code, message: error.message, field: error.field });
}

export async function registerMetadataRoutes(app: FastifyInstance, previewer?: MetadataPreviewer) {
  const bookmarks = new BookmarkRepository(app.database);

  app.post<{ Body: MetadataPreviewRequest }>(
    "/api/metadata/preview",
    { schema: { body: MetadataPreviewRequestSchema } },
    async (request, reply) => {
      try {
        const normalized = normalizeAddress(request.body.address);
        const existing = bookmarks.findIdentityByNormalizedAddress(normalized.normalizedAddress);
        if (existing) {
          return reply.code(409).send({
            code: "DUPLICATE_BOOKMARK",
            message: "That address is already saved. Open the existing bookmark to edit it.",
            field: "address",
            existingBookmarkId: existing.id,
            existingScope: existing.archived ? "archived" : "active",
          });
        }
        return previewer?.preview(normalized.address) ?? fallbackPreview(normalized.address);
      } catch (error) {
        if (error instanceof AddressValidationError) return addressProblem(reply, error);
        throw error;
      }
    },
  );
}
import pLimit from "p-limit";
import type { MetadataPreview, MetadataStatus } from "../../../shared/contracts/api.js";
import type { AppConfig } from "../../config.js";
import type { AppDatabase } from "../../db/database.js";
import { BookmarkRepository } from "../../repositories/bookmark-repository.js";
import { IconRepository } from "../../repositories/icon-repository.js";
import { fallbackTitleFromAddress } from "../bookmarks/address-normalizer.js";
import { extractPageMetadata, type ExtractedPageMetadata } from "./extract-metadata.js";
import {
  fetchHtml,
  fetchRasterImage,
  SafeMetadataFetchError,
  type SafeFetchResult,
} from "./safe-fetch.js";
import { processIconOrNull, type ProcessedIcon } from "./process-icon.js";

export interface MetadataFetchFunctions {
  html: (address: string) => Promise<SafeFetchResult>;
  icon: (address: string) => Promise<SafeFetchResult>;
}

export interface MetadataCoordinatorOptions {
  database: AppDatabase;
  config: AppConfig["metadata"];
  now?: () => Date;
  fetch?: Partial<MetadataFetchFunctions>;
}

interface RetrievedMetadata {
  extracted: ExtractedPageMetadata;
  icon: ProcessedIcon | null;
}

function errorCode(error: unknown): string {
  if (!(error instanceof SafeMetadataFetchError)) return "unavailable";
  const mapping: Record<string, string> = {
    TIMEOUT: "timeout",
    DENIED_DESTINATION: "denied_destination",
    UNSUPPORTED_PROTOCOL: "denied_destination",
    UNSUPPORTED_CONTENT_TYPE: "unsupported_content",
    TOO_LARGE: "too_large",
  };
  return mapping[error.code] ?? "unavailable";
}

function errorStatus(error: unknown): MetadataStatus {
  return error instanceof SafeMetadataFetchError &&
    (error.code === "DENIED_DESTINATION" || error.code === "UNSUPPORTED_PROTOCOL")
    ? "skipped_unsafe"
    : "failed";
}

export class MetadataCoordinator {
  private readonly bookmarks: BookmarkRepository;
  private readonly icons: IconRepository;
  private readonly now: () => Date;
  private readonly fetchers: MetadataFetchFunctions;
  private readonly limit: ReturnType<typeof pLimit>;
  private readonly scheduled = new Set<string>();
  private readonly pending = new Set<Promise<void>>();

  constructor(private readonly options: MetadataCoordinatorOptions) {
    this.bookmarks = new BookmarkRepository(options.database);
    this.icons = new IconRepository(options.database);
    this.now = options.now ?? (() => new Date());
    this.limit = pLimit(options.config.concurrency);
    this.fetchers = {
      html:
        options.fetch?.html ??
        ((address) =>
          fetchHtml(address, {
            deadlineMs: options.config.deadlineMs,
            connectTimeoutMs: options.config.connectTimeoutMs,
            maxBytes: options.config.maxHtmlBytes,
            maxRedirects: options.config.maxRedirects,
          })),
      icon:
        options.fetch?.icon ??
        ((address) =>
          fetchRasterImage(address, {
            deadlineMs: options.config.deadlineMs,
            connectTimeoutMs: options.config.connectTimeoutMs,
            maxBytes: options.config.maxIconBytes,
            maxRedirects: options.config.maxRedirects,
          })),
    };
  }

  start(): void {
    for (const item of this.bookmarks.pendingMetadata()) {
      this.enqueue(item.id, item.address, item.addressRevision);
    }
  }

  enqueue(bookmarkId: number, address: string, addressRevision: number): void {
    const key = `${bookmarkId}:${addressRevision}`;
    if (this.scheduled.has(key)) return;
    this.scheduled.add(key);
    const job = this.limit(() => this.enrich(bookmarkId, address, addressRevision))
      .catch(() => undefined)
      .finally(() => {
        this.scheduled.delete(key);
        this.pending.delete(job);
      });
    this.pending.add(job);
  }

  async drain(): Promise<void> {
    await Promise.all([...this.pending]);
  }

  async preview(address: string): Promise<MetadataPreview> {
    const fallbackTitle = fallbackTitleFromAddress(address);
    try {
      const result = await this.retrieve(address);
      const hasRetrievedText =
        result.extracted.titleSource !== "fallback" || result.extracted.description !== "";
      return {
        address,
        status: hasRetrievedText || result.icon ? "complete" : "partial",
        fallbackTitle,
        title: result.extracted.title,
        description: result.extracted.description,
        iconAvailable: result.icon !== null,
        errorCode: null,
      };
    } catch (error) {
      return {
        address,
        status: errorStatus(error),
        fallbackTitle,
        title: fallbackTitle,
        description: "",
        iconAvailable: false,
        errorCode: errorCode(error),
      };
    }
  }

  private async retrieve(address: string): Promise<RetrievedMetadata> {
    const page = await this.fetchers.html(address);
    const extracted = extractPageMetadata(page.body, page.finalUrl);
    let icon: ProcessedIcon | null = null;
    for (const candidate of extracted.iconCandidates) {
      try {
        const response = await this.fetchers.icon(candidate.url);
        icon = await processIconOrNull(response.body, {
          contentType: response.contentType,
          maxInputBytes: this.options.config.maxIconBytes,
        });
        if (icon) break;
      } catch {
        // An icon is optional. Try the next declared/fallback candidate.
      }
    }
    return { extracted, icon };
  }

  private async enrich(
    bookmarkId: number,
    address: string,
    addressRevision: number,
  ): Promise<void> {
    try {
      const result = await this.retrieve(address);
      const fetchedAt = this.now().toISOString();
      if (result.icon) this.icons.put({ ...result.icon, createdAt: fetchedAt });
      const hasTitle = result.extracted.titleSource !== "fallback";
      const hasDescription = result.extracted.description !== "";
      const hasIcon = result.icon !== null;
      this.bookmarks.applyMetadata({
        bookmarkId,
        addressRevision,
        ...(hasTitle ? { title: result.extracted.title } : {}),
        ...(hasDescription ? { description: result.extracted.description } : {}),
        ...(result.icon ? { iconHash: result.icon.contentHash } : {}),
        status:
          hasTitle && hasDescription
            ? "complete"
            : hasTitle || hasDescription || hasIcon
              ? "partial"
              : "failed",
        errorCode: hasTitle || hasDescription || hasIcon ? null : "metadata_missing",
        fetchedAt,
      });
    } catch (error) {
      this.bookmarks.applyMetadata({
        bookmarkId,
        addressRevision,
        status: errorStatus(error),
        errorCode: errorCode(error),
        fetchedAt: this.now().toISOString(),
      });
    }
  }
}
import { type NormalizedAddress, normalizeAddress } from "../../../shared/types/address.js";

const MAX_FALLBACK_TITLE_LENGTH = 120;
const TITLE_SEPARATOR = " \u2014 ";

function decodePathSegment(segment: string): string {
  try {
    return decodeURIComponent(segment);
  } catch {
    return segment;
  }
}

function truncate(value: string, maximum: number): string {
  if (value.length <= maximum) return value;
  if (maximum <= 1) return "\u2026".slice(0, maximum);
  return `${value.slice(0, maximum - 1).trimEnd()}\u2026`;
}

function displayHost(hostname: string): string {
  const withoutCommonPrefix = hostname.replace(/^www\./iu, "");
  return truncate(withoutCommonPrefix, MAX_FALLBACK_TITLE_LENGTH);
}

function readablePathLabel(pathname: string): string {
  const segments = pathname.split("/").filter(Boolean);
  const lastSegment = segments.at(-1);
  if (!lastSegment) return "";

  const decoded = decodePathSegment(lastSegment);
  const words = decoded.replace(/[-_]+/gu, " ").replace(/\s+/gu, " ").trim();
  if (words === "") return "";

  return `${words.charAt(0).toLocaleUpperCase("en-US")}${words.slice(1)}`;
}

/** Generates a stable, non-empty title while remote metadata is unavailable. */
export function fallbackTitleFromAddress(address: string): string {
  const { url } = normalizeAddress(address);
  const host = displayHost(url.hostname);
  const pathLabel = readablePathLabel(url.pathname);
  if (pathLabel === "") return host;

  const availablePathLength = Math.max(
    1,
    MAX_FALLBACK_TITLE_LENGTH - host.length - TITLE_SEPARATOR.length,
  );
  return `${truncate(pathLabel, availablePathLength)}${TITLE_SEPARATOR}${host}`;
}

export type { NormalizedAddress };
export { normalizeAddress };
export const ADDRESS_ERROR_CODES = {
  required: "ADDRESS_REQUIRED",
  invalid: "ADDRESS_INVALID",
  unsupportedScheme: "ADDRESS_UNSUPPORTED_SCHEME",
} as const;

export type AddressValidationErrorCode =
  (typeof ADDRESS_ERROR_CODES)[keyof typeof ADDRESS_ERROR_CODES];

/** A field-specific failure safe to map to an API problem or inline form guidance. */
export class AddressValidationError extends Error {
  readonly field = "address" as const;

  constructor(
    readonly code: AddressValidationErrorCode,
    message: string,
  ) {
    super(message);
    this.name = "AddressValidationError";
  }
}

export interface NormalizedAddress {
  /** The user's destination with surrounding whitespace removed. */
  address: string;
  /** The exact key used by the database uniqueness constraint. */
  normalizedAddress: string;
  /** The successfully parsed WHATWG URL. */
  url: URL;
}

const SCHEME_PATTERN = /^([A-Za-z][A-Za-z\d+.-]*):/u;
const EXPLICIT_AUTHORITY_PATTERN = /^([A-Za-z][A-Za-z\d+.-]*):\/\/([^/?#]*)(.*)$/su;

function containsAsciiControl(value: string): boolean {
  for (let index = 0; index < value.length; index += 1) {
    const code = value.charCodeAt(index);
    if (code <= 31 || code === 127) return true;
  }
  return false;
}

function invalidAddress(
  message = "Enter a complete web address, such as https://example.com.",
): never {
  throw new AddressValidationError(ADDRESS_ERROR_CODES.invalid, message);
}

function rawPortFromAuthority(authority: string): string | undefined {
  const hostAndPort = authority.slice(authority.lastIndexOf("@") + 1);

  if (hostAndPort.startsWith("[")) {
    const closingBracket = hostAndPort.indexOf("]");
    if (closingBracket === -1) {
      return invalidAddress();
    }

    const remainder = hostAndPort.slice(closingBracket + 1);
    if (remainder === "") return undefined;
    if (!remainder.startsWith(":")) return invalidAddress();
    return remainder.slice(1);
  }

  const colon = hostAndPort.lastIndexOf(":");
  return colon === -1 ? undefined : hostAndPort.slice(colon + 1);
}

/**
 * Validates a bookmark destination with the WHATWG parser and derives the
 * deliberately narrow FR-005 identity. Path, query and fragment source text
 * stays distinct; only scheme/host case, default ports, and the root path are
 * normalized.
 */
export function normalizeAddress(input: string): NormalizedAddress {
  const address = input.trim();
  if (address === "") {
    throw new AddressValidationError(ADDRESS_ERROR_CODES.required, "Enter a web address to save.");
  }

  const schemeMatch = SCHEME_PATTERN.exec(address);
  if (schemeMatch && !/^https?$/iu.test(schemeMatch[1] ?? "")) {
    throw new AddressValidationError(
      ADDRESS_ERROR_CODES.unsupportedScheme,
      "Use an address beginning with http:// or https://.",
    );
  }

  const sourceMatch = EXPLICIT_AUTHORITY_PATTERN.exec(address);
  if (!sourceMatch || containsAsciiControl(address)) return invalidAddress();

  const [, rawScheme = "", rawAuthority = "", rawSuffix = ""] = sourceMatch;
  if (!/^https?$/iu.test(rawScheme) || rawAuthority === "") return invalidAddress();

  // For special URLs WHATWG treats backslashes as slashes. Reject that
  // surprising spelling outside query/fragment instead of silently changing
  // its destination or duplicate identity.
  const beforeQueryOrFragment = address.split(/[?#]/u, 1)[0] ?? address;
  if (beforeQueryOrFragment.includes("\\")) return invalidAddress();

  const rawPort = rawPortFromAuthority(rawAuthority);
  if (rawPort !== undefined && !/^\d+$/u.test(rawPort)) return invalidAddress();

  let url: URL;
  try {
    url = new URL(address);
  } catch {
    return invalidAddress();
  }

  if ((url.protocol !== "http:" && url.protocol !== "https:") || url.hostname === "") {
    return invalidAddress();
  }

  const at = rawAuthority.lastIndexOf("@");
  const credentials = at === -1 ? "" : rawAuthority.slice(0, at + 1);
  const port = url.port === "" ? "" : `:${url.port}`;
  const suffix = rawSuffix === "" ? "/" : /^[?#]/u.test(rawSuffix) ? `/${rawSuffix}` : rawSuffix;
  const normalizedAddress = `${url.protocol}//${credentials}${url.hostname.toLowerCase()}${port}${suffix}`;

  return { address, normalizedAddress, url };
}

export function addressesHaveSameIdentity(left: string, right: string): boolean {
  return normalizeAddress(left).normalizedAddress === normalizeAddress(right).normalizedAddress;
}
import type { Scope, SearchCriteria, SortOrder } from "./api";

export interface ViewState extends SearchCriteria {
  favorite: boolean | null;
  unread: boolean | null;
  bookmarkId: number | null;
  editing: boolean;
  savedViewId: number | null;
  cursor: string | null;
}

export const DEFAULT_VIEW_STATE: Readonly<ViewState> = {
  scope: "active",
  query: "",
  tags: [],
  favorite: null,
  unread: null,
  sort: "created_desc",
  bookmarkId: null,
  editing: false,
  savedViewId: null,
  cursor: null,
};

const scopes = new Set<Scope>(["active", "read_later", "archived"]);
const sorts = new Set<SortOrder>(["created_desc", "created_asc", "updated_desc", "title_asc"]);

function nullableBoolean(value: string | null): boolean | null {
  if (value === "true") return true;
  if (value === "false") return false;
  return null;
}

function positiveInteger(value: string | null): number | null {
  if (value === null || !/^\d+$/.test(value)) return null;
  const result = Number(value);
  return Number.isSafeInteger(result) && result > 0 ? result : null;
}

export function parseViewState(input: string | URLSearchParams): ViewState {
  const parameters =
    typeof input === "string"
      ? new URLSearchParams(input.startsWith("?") ? input.slice(1) : input)
      : input;
  const scopeValue = parameters.get("scope") as Scope | null;
  const sortValue = parameters.get("sort") as SortOrder | null;
  const bookmarkId = positiveInteger(parameters.get("bookmark"));

  return {
    scope: scopeValue && scopes.has(scopeValue) ? scopeValue : DEFAULT_VIEW_STATE.scope,
    query: parameters.get("q") ?? DEFAULT_VIEW_STATE.query,
    tags: Array.from(
      new Set(
        parameters
          .getAll("tag")
          .map((tag) => tag.trim())
          .filter(Boolean),
      ),
    ),
    favorite: nullableBoolean(parameters.get("favorite")),
    unread: nullableBoolean(parameters.get("unread")),
    sort: sortValue && sorts.has(sortValue) ? sortValue : DEFAULT_VIEW_STATE.sort,
    bookmarkId,
    editing: bookmarkId !== null && parameters.get("edit") === "true",
    savedViewId: positiveInteger(parameters.get("view")),
    cursor: parameters.get("cursor") || null,
  };
}

export function viewStateToSearchParams(state: ViewState): URLSearchParams {
  const parameters = new URLSearchParams();

  if (state.scope !== DEFAULT_VIEW_STATE.scope) parameters.set("scope", state.scope);
  if (state.query) parameters.set("q", state.query);
  for (const tag of state.tags) parameters.append("tag", tag);
  if (state.favorite !== null) parameters.set("favorite", String(state.favorite));
  if (state.unread !== null) parameters.set("unread", String(state.unread));
  if (state.sort !== DEFAULT_VIEW_STATE.sort) parameters.set("sort", state.sort);
  if (state.bookmarkId !== null) parameters.set("bookmark", String(state.bookmarkId));
  if (state.editing && state.bookmarkId !== null) parameters.set("edit", "true");
  if (state.savedViewId !== null) parameters.set("view", String(state.savedViewId));
  if (state.cursor) parameters.set("cursor", state.cursor);

  return parameters;
}

export function serializeViewState(state: ViewState): string {
  const value = viewStateToSearchParams(state).toString();
  return value ? `?${value}` : "";
}

export function readViewState(location: Pick<Location, "search"> = window.location): ViewState {
  return parseViewState(location.search);
}

export function viewStateHref(
  state: ViewState,
  location: Pick<Location, "pathname" | "hash"> = window.location,
): string {
  return `${location.pathname}${serializeViewState(state)}${location.hash}`;
}

export function writeViewState(
  state: ViewState,
  mode: "push" | "replace" = "push",
  history: Pick<History, "pushState" | "replaceState"> = window.history,
): void {
  const method =
    mode === "replace" ? history.replaceState.bind(history) : history.pushState.bind(history);
  method(null, "", viewStateHref(state));
  window.dispatchEvent(new CustomEvent("bookmark-garden:view-state"));
}

export function subscribeToViewState(listener: (state: ViewState) => void): () => void {
  const handleChange = () => listener(readViewState());
  window.addEventListener("popstate", handleChange);
  window.addEventListener("bookmark-garden:view-state", handleChange);
  return () => {
    window.removeEventListener("popstate", handleChange);
    window.removeEventListener("bookmark-garden:view-state", handleChange);
  };
}

export function criteriaFromViewState(state: ViewState): SearchCriteria {
  return {
    scope: state.scope,
    query: state.query,
    tags: [...state.tags],
    favorite: state.favorite,
    unread: state.unread,
    sort: state.sort,
  };
}

export function resetPagination(state: ViewState): ViewState {
  return { ...state, cursor: null };
}

export function withScope(state: ViewState, scope: Scope): ViewState {
  return {
    ...state,
    scope,
    bookmarkId: null,
    editing: false,
    savedViewId: null,
    cursor: null,
  };
}
