export function App() {
  const [startup, setStartup] = useState<StartupState>("loading");
  const [view, setView] = useState<ViewState>(() => readViewState());
  const [collection, setCollection] = useState<BookmarkPage | null>(null);
  const [collectionError, setCollectionError] = useState(false);
  const [tags, setTags] = useState<TagSummary[]>([]);
  const [captureOpen, setCaptureOpen] = useState(false);
  const [selectedBookmark, setSelectedBookmark] = useState<Bookmark | null>(null);
  const captureAddressRef = useRef<HTMLInputElement>(null);

  useEffect(() => subscribeToViewState(setView), []);

  useEffect(() => {
    const controller = new AbortController();
    setStartup("loading");
    api
      .getHealth({ signal: controller.signal })
      .then(() => setStartup("ready"))
      .catch((error: unknown) => {
        if (!(error instanceof DOMException && error.name === "AbortError")) setStartup("error");
      });
    return () => controller.abort();
  }, []);

  useEffect(() => {
    if (startup !== "ready") return;
    const controller = new AbortController();
    setCollection(null);
    setCollectionError(false);
    api
      .listBookmarks(
        {
          scope: view.scope,
          query: view.query,
          tags: view.tags,
          favorite: view.favorite,
          unread: view.unread,
          sort: view.sort,
          ...(view.cursor ? { cursor: view.cursor } : {}),
        },
        { signal: controller.signal },
      )
      .then(setCollection)
      .catch((error: unknown) => {
        if (!(error instanceof DOMException && error.name === "AbortError")) {
          setCollectionError(true);
        }
      });
    return () => controller.abort();
  }, [startup, view]);

  useEffect(() => {
    if (startup !== "ready") return;
    const controller = new AbortController();
    api
      .listTags({ signal: controller.signal })
      .then(setTags)
      .catch(() => setTags([]));
    return () => controller.abort();
  }, [startup, collection?.total]);

  useEffect(() => {
    if (startup !== "ready" || view.bookmarkId === null) return;
    const fromPage = collection?.items.find((bookmark) => bookmark.id === view.bookmarkId);
    if (fromPage) {
      setSelectedBookmark(fromPage);
      return;
    }
    const controller = new AbortController();
    api
      .getBookmark(view.bookmarkId, { signal: controller.signal })
      .then(setSelectedBookmark)
      .catch((error: unknown) => {
        if (!(error instanceof DOMException && error.name === "AbortError")) {
          setSelectedBookmark(null);
        }
      });
    return () => controller.abort();
  }, [collection, startup, view.bookmarkId]);

  function navigate(scope: ViewState["scope"]) {
    setSelectedBookmark(null);
    const next = withScope(view, scope);
    writeViewState(next);
  }

  function updateView(next: ViewState) {
    setSelectedBookmark(null);
    writeViewState({ ...next, bookmarkId: null, editing: false });
  }

  function openBookmark(bookmark: Bookmark, editing = false) {
    setSelectedBookmark(bookmark);
    writeViewState({ ...view, bookmarkId: bookmark.id, editing });
  }

  function closeBookmark() {
    setSelectedBookmark(null);
    writeViewState({ ...view, bookmarkId: null, editing: false }, "replace");
  }

  function handleSaved(bookmark: Bookmark) {
    setCaptureOpen(false);
    if (view.scope === "active") {
      setCollection((current) =>
        current
          ? { ...current, items: [bookmark, ...current.items], total: current.total + 1 }
          : current,
      );
    }
    openBookmark(bookmark);
  }

  function handleDuplicate(bookmarkId: number, scope?: Scope) {
    setCaptureOpen(false);
    const next = {
      ...view,
      scope: scope ?? view.scope,
      bookmarkId,
      editing: true,
      cursor: null,
    };
    writeViewState(next);
  }

  if (startup === "loading") return <LoadingShell />;
  if (startup === "error") return <StartupError onRetry={() => window.location.reload()} />;

  const copy = scopeCopy[view.scope];
  const hasCriteria = Boolean(
    view.query || view.tags.length || view.favorite !== null || view.unread !== null,
  );

  return (
    <div
      className="app-shell"
      data-harness-ready={collection !== null || collectionError ? "true" : undefined}
    >
      <a className="skip-link" href="#main-content">
        Skip to collection
      </a>
      <header className="site-header">
        <a
          className="brand"
          href={viewStateHref(withScope(view, "active"))}
          onClick={(event) => {
            event.preventDefault();
            navigate("active");
          }}
        >
          <BrandMark />
          <span>
            <strong>Bookmark Garden</strong>
            <small>Links, thoughtfully kept</small>
          </span>
        </a>
        <div className="header-actions">
          <Button variant="primary" onClick={() => setCaptureOpen(true)}>
            <span aria-hidden="true">＋</span> Add bookmark
          </Button>
        </div>
      </header>

      <div className="app-layout">
        <aside className="sidebar" aria-label="Collection navigation">
          <nav>
            <p className="nav-label">Library</p>
            <ul className="nav-list">
              {(Object.keys(scopeCopy) as ViewState["scope"][]).map((scope) => (
                <li key={scope}>
                  <a
                    href={viewStateHref(withScope(view, scope))}
                    className={view.scope === scope ? "nav-link nav-link--active" : "nav-link"}
                    aria-current={view.scope === scope ? "page" : undefined}
                    onClick={(event) => {
                      event.preventDefault();
                      navigate(scope);
                    }}
                  >
                    <span>{scopeCopy[scope].label}</span>
                  </a>
                </li>
              ))}
            </ul>
          </nav>
          <div className="sidebar-note">
            <span aria-hidden="true">✦</span>
            <p>Saved views will keep your favorite searches close at hand.</p>
          </div>
        </aside>

        <main id="main-content" className="main-content" tabIndex={-1}>
          <section className="page-heading">
            <div>
              <p className="eyebrow">{copy.eyebrow}</p>
              <h1>{copy.title}</h1>
            </div>
            <Status live="off">Ready for your links</Status>
          </section>

          <SearchControls
            view={view}
            tags={tags}
            total={collection?.total ?? 0}
            onChange={updateView}
          />

          <section className="collection-panel" aria-labelledby="collection-title">
            <div className="collection-panel__header">
              <div>
                <p className="eyebrow">Current view</p>
                <h2 id="collection-title">{copy.label}</h2>
              </div>
              <span className="result-count">
                {collection
                  ? `${collection.total} bookmark${collection.total === 1 ? "" : "s"}`
                  : ""}
              </span>
            </div>
            {collectionError ? (
              <EmptyState
                title="This collection could not be loaded"
                description="Your bookmarks have not been changed. Reload the page to try again."
                action={<Button onClick={() => window.location.reload()}>Reload</Button>}
              />
            ) : collection === null ? (
              <div className="collection-loading" role="status" aria-live="polite">
                Loading bookmarks…
              </div>
            ) : collection.items.length ? (
              <>
                <BookmarkList bookmarks={collection.items} onOpen={openBookmark} />
                {collection.nextCursor ? (
                  <div className="collection-pagination">
                    <Button onClick={() => updateView({ ...view, cursor: collection.nextCursor })}>
                      Load more results
                    </Button>
                  </div>
                ) : null}
              </>
            ) : (
              <EmptyState
                title={hasCriteria ? "No bookmarks match this view" : copy.emptyTitle}
                description={
                  hasCriteria
                    ? "Try removing a filter or simplifying the search expression."
                    : copy.emptyDescription
                }
                icon={<BrandMark />}
                action={
                  hasCriteria ? (
                    <Button
                      onClick={() =>
                        updateView({
                          ...view,
                          query: "",
                          tags: [],
                          favorite: null,
                          unread: null,
                          cursor: null,
                        })
                      }
                    >
                      Clear search and filters
                    </Button>
                  ) : view.scope === "active" ? (
                    <Button variant="primary" onClick={() => setCaptureOpen(true)}>
                      Add your first bookmark
                    </Button>
                  ) : undefined
                }
              />
            )}
          </section>
        </main>
      </div>

      <footer className="site-footer">
        <p>Your collection stays on this app installation.</p>
      </footer>

      <Dialog
        open={captureOpen}
        title="Save a bookmark"
        description="Paste an address and save right away. Page details will arrive automatically when available."
        onClose={() => setCaptureOpen(false)}
        initialFocusRef={captureAddressRef}
      >
        <CaptureForm
          addressInputRef={captureAddressRef}
          onSaved={handleSaved}
          onDuplicate={handleDuplicate}
          onCancel={() => setCaptureOpen(false)}
        />
      </Dialog>

      {selectedBookmark ? (
        <BookmarkDetail
          bookmark={selectedBookmark}
          editing={view.editing}
          onClose={closeBookmark}
        />
      ) : null}
    </div>
  );
}
import type { FastifyInstance, FastifyReply } from "fastify";
import {
  BookmarkCreateSchema,
  BookmarkIdParamsSchema,
  BookmarkListQuerySchema,
  type BookmarkCreate,
  type BookmarkIdParams,
  type BookmarkListQuery,
} from "../../shared/contracts/api.js";
import { AddressValidationError } from "../../shared/types/address.js";
import {
  BookmarkNotFoundError,
  BookmarkRepository,
  DuplicateBookmarkError,
} from "../repositories/bookmark-repository.js";
import { IconRepository } from "../repositories/icon-repository.js";
import {
  fallbackTitleFromAddress,
  normalizeAddress,
} from "../services/bookmarks/address-normalizer.js";

export interface MetadataQueue {
  enqueue(bookmarkId: number, address: string, addressRevision: number): void;
}

function sendAddressProblem(reply: FastifyReply, error: AddressValidationError) {
  return reply.code(422).send({ code: error.code, message: error.message, field: error.field });
}

function sendDuplicate(reply: FastifyReply, error: DuplicateBookmarkError) {
  return reply.code(409).send({
    code: "DUPLICATE_BOOKMARK",
    message: "That address is already saved. Open the existing bookmark to edit it.",
    field: "address",
    existingBookmarkId: error.identity.id,
    existingScope: error.identity.archived ? "archived" : "active",
  });
}

export async function registerBookmarkRoutes(app: FastifyInstance, metadataQueue?: MetadataQueue) {
  const bookmarks = new BookmarkRepository(app.database);
  const icons = new IconRepository(app.database);

  app.post<{ Body: BookmarkCreate }>(
    "/api/bookmarks",
    { schema: { body: BookmarkCreateSchema } },
    async (request, reply) => {
      try {
        const normalized = normalizeAddress(request.body.address);
        const bookmark = bookmarks.create({
          input: request.body,
          address: normalized.address,
          normalizedAddress: normalized.normalizedAddress,
          fallbackTitle: fallbackTitleFromAddress(normalized.address),
          now: app.now().toISOString(),
        });
        const row = bookmarks.getRow(bookmark.id);
        if (row) metadataQueue?.enqueue(bookmark.id, bookmark.address, row.address_revision);
        return reply.code(201).send(bookmark);
      } catch (error) {
        if (error instanceof AddressValidationError) return sendAddressProblem(reply, error);
        if (error instanceof DuplicateBookmarkError) return sendDuplicate(reply, error);
        throw error;
      }
    },
  );

  app.get<{ Querystring: BookmarkListQuery }>(
    "/api/bookmarks",
    { schema: { querystring: BookmarkListQuerySchema } },
    async (request) => bookmarks.listActive(request.query.limit),
  );

  app.get<{ Params: BookmarkIdParams }>(
    "/api/bookmarks/:bookmarkId",
    { schema: { params: BookmarkIdParamsSchema } },
    async (request, reply) => {
      try {
        return bookmarks.get(request.params.bookmarkId);
      } catch (error) {
        if (error instanceof BookmarkNotFoundError) {
          return reply.code(404).send({ code: "BOOKMARK_NOT_FOUND", message: error.message });
        }
        throw error;
      }
    },
  );

  app.get<{ Params: BookmarkIdParams }>(
    "/api/bookmarks/:bookmarkId/icon",
    { schema: { params: BookmarkIdParamsSchema } },
    async (request, reply) => {
      const bytes = icons.getForBookmark(request.params.bookmarkId);
      if (!bytes) return reply.code(404).send();
      return reply
        .header("Content-Type", "image/png")
        .header("X-Content-Type-Options", "nosniff")
        .header("Cache-Control", "public, max-age=31536000, immutable")
        .send(bytes);
    },
  );
}
