import type {
  Bookmark,
  BookmarkCreate,
  BookmarkPage,
  MetadataStatus,
  Provenance,
} from "../../shared/contracts/api.js";
import type { AppDatabase } from "../db/database.js";

export interface CreateBookmarkValues {
  input: BookmarkCreate;
  address: string;
  normalizedAddress: string;
  fallbackTitle: string;
  now: string;
}

export interface BookmarkIdentity {
  id: number;
  archived: boolean;
}

export interface MetadataUpdate {
  bookmarkId: number;
  addressRevision: number;
  title?: string;
  description?: string;
  iconHash?: string | null;
  status: MetadataStatus;
  errorCode?: string | null;
  fetchedAt: string;
}

interface BookmarkRow {
  id: number;
  address: string;
  normalized_address: string;
  address_revision: number;
  title: string;
  title_sort_key: string;
  title_provenance: Provenance;
  retrieved_title_candidate: string | null;
  description: string;
  description_provenance: Provenance;
  retrieved_description_candidate: string | null;
  icon_hash: string | null;
  metadata_status: MetadataStatus;
  metadata_error_code: string | null;
  metadata_fetched_at: string | null;
  note_markdown: string;
  note_plain: string;
  is_favorite: 0 | 1;
  is_unread: 0 | 1;
  archived_at: string | null;
  created_at: string;
  updated_at: string;
}

export class DuplicateBookmarkError extends Error {
  readonly identity: BookmarkIdentity;

  constructor(identity: BookmarkIdentity) {
    super("That address is already saved.");
    this.name = "DuplicateBookmarkError";
    this.identity = identity;
  }
}

export class BookmarkNotFoundError extends Error {
  constructor() {
    super("Bookmark not found.");
    this.name = "BookmarkNotFoundError";
  }
}

export function titleSortKey(title: string): string {
  return title.normalize("NFKC").toLocaleLowerCase("und");
}

function toBookmark(row: BookmarkRow): Bookmark {
  return {
    id: row.id,
    address: row.address,
    title: row.title,
    titleProvenance: row.title_provenance,
    retrievedTitleCandidate: row.retrieved_title_candidate,
    description: row.description,
    descriptionProvenance: row.description_provenance,
    retrievedDescriptionCandidate: row.retrieved_description_candidate,
    iconUrl: row.icon_hash ? `/api/bookmarks/${row.id}/icon` : null,
    metadataStatus: row.metadata_status,
    metadataErrorCode: row.metadata_error_code,
    noteMarkdown: row.note_markdown,
    tags: [],
    favorite: row.is_favorite === 1,
    unread: row.is_unread === 1,
    archived: row.archived_at !== null,
    createdAt: row.created_at,
    updatedAt: row.updated_at,
  };
}

function rowForNormalizedAddress(
  database: AppDatabase,
  normalizedAddress: string,
): BookmarkRow | undefined {
  return database
    .prepare("SELECT * FROM bookmarks WHERE normalized_address = ?")
    .get(normalizedAddress) as BookmarkRow | undefined;
}

export class BookmarkRepository {
  constructor(private readonly database: AppDatabase) {}

  findIdentityByNormalizedAddress(normalizedAddress: string): BookmarkIdentity | null {
    const row = rowForNormalizedAddress(this.database, normalizedAddress);
    return row ? { id: row.id, archived: row.archived_at !== null } : null;
  }

  create(values: CreateBookmarkValues): Bookmark {
    const existing = this.findIdentityByNormalizedAddress(values.normalizedAddress);
    if (existing) throw new DuplicateBookmarkError(existing);

    const titleWasSupplied = values.input.title !== undefined;
    const descriptionWasSupplied = values.input.description !== undefined;
    const title = titleWasSupplied
      ? values.input.title?.trim() || values.fallbackTitle
      : values.fallbackTitle;
    const description = descriptionWasSupplied ? (values.input.description?.trim() ?? "") : "";

    try {
      const result = this.database
        .prepare(`
          INSERT INTO bookmarks (
            address, normalized_address, title, title_sort_key, title_provenance,
            description, description_provenance, metadata_status, note_markdown,
            note_plain, is_favorite, is_unread, created_at, updated_at
          ) VALUES (?, ?, ?, ?, ?, ?, ?, 'pending', ?, '', ?, ?, ?, ?)
        `)
        .run(
          values.address,
          values.normalizedAddress,
          title,
          titleSortKey(title),
          titleWasSupplied ? "user" : "fallback",
          description,
          descriptionWasSupplied ? "user" : "fallback",
          values.input.noteMarkdown ?? "",
          values.input.favorite ? 1 : 0,
          values.input.unread ? 1 : 0,
          values.now,
          values.now,
        );
      return this.get(Number(result.lastInsertRowid));
    } catch (error) {
      const raced = this.findIdentityByNormalizedAddress(values.normalizedAddress);
      if (raced) throw new DuplicateBookmarkError(raced);
      throw error;
    }
  }

  get(id: number): Bookmark {
    const row = this.database.prepare("SELECT * FROM bookmarks WHERE id = ?").get(id) as
      | BookmarkRow
      | undefined;
    if (!row) throw new BookmarkNotFoundError();
    return toBookmark(row);
  }

  getRow(id: number): BookmarkRow | null {
    return (
      (this.database.prepare("SELECT * FROM bookmarks WHERE id = ?").get(id) as
        | BookmarkRow
        | undefined) ?? null
    );
  }

  listActive(limit = 50): BookmarkPage {
    const safeLimit = Math.max(1, Math.min(limit, 100));
    const rows = this.database
      .prepare(
        "SELECT * FROM bookmarks WHERE archived_at IS NULL ORDER BY created_at DESC, id DESC LIMIT ?",
      )
      .all(safeLimit) as BookmarkRow[];
    const total = (
      this.database
        .prepare("SELECT count(*) AS count FROM bookmarks WHERE archived_at IS NULL")
        .get() as { count: number }
    ).count;
    return { items: rows.map(toBookmark), total, nextCursor: null };
  }

  applyMetadata(update: MetadataUpdate): boolean {
    const row = this.getRow(update.bookmarkId);
    if (!row || row.address_revision !== update.addressRevision) return false;

    const title = update.title?.trim();
    const description = update.description?.trim();
    const titleCanApply = Boolean(title) && row.title_provenance !== "user";
    const descriptionCanApply = description !== undefined && row.description_provenance !== "user";

    const result = this.database
      .prepare(`
        UPDATE bookmarks SET
          title = CASE WHEN @titleCanApply THEN @title ELSE title END,
          title_sort_key = CASE WHEN @titleCanApply THEN @titleSortKey ELSE title_sort_key END,
          title_provenance = CASE WHEN @titleCanApply THEN 'retrieved' ELSE title_provenance END,
          retrieved_title_candidate = CASE WHEN @title IS NOT NULL AND title_provenance = 'user' THEN @title ELSE retrieved_title_candidate END,
          description = CASE WHEN @descriptionCanApply THEN @description ELSE description END,
          description_provenance = CASE WHEN @descriptionCanApply THEN 'retrieved' ELSE description_provenance END,
          retrieved_description_candidate = CASE WHEN @description IS NOT NULL AND description_provenance = 'user' THEN @description ELSE retrieved_description_candidate END,
          icon_hash = COALESCE(@iconHash, icon_hash),
          metadata_status = @status,
          metadata_error_code = @errorCode,
          metadata_fetched_at = @fetchedAt,
          updated_at = @fetchedAt
        WHERE id = @bookmarkId AND address_revision = @addressRevision
      `)
      .run({
        bookmarkId: update.bookmarkId,
        addressRevision: update.addressRevision,
        title: title ?? null,
        titleCanApply: titleCanApply ? 1 : 0,
        titleSortKey: title ? titleSortKey(title) : row.title_sort_key,
        description: description ?? null,
        descriptionCanApply: descriptionCanApply ? 1 : 0,
        iconHash: update.iconHash ?? null,
        status: update.status,
        errorCode: update.errorCode ?? null,
        fetchedAt: update.fetchedAt,
      });
    return result.changes === 1;
  }

  pendingMetadata(): Array<{ id: number; address: string; addressRevision: number }> {
    return this.database
      .prepare(
        "SELECT id, address, address_revision AS addressRevision FROM bookmarks WHERE metadata_status = 'pending'",
      )
      .all() as Array<{ id: number; address: string; addressRevision: number }>;
  }
}
-- Creating this table is also the startup capability check for both FTS5 and
-- its trigram tokenizer. SQLite aborts this transactional migration before the
-- application becomes ready if either capability is unavailable.
CREATE TABLE tags (
  id INTEGER PRIMARY KEY,
  display_name TEXT NOT NULL CHECK (length(trim(display_name)) > 0),
  name_key TEXT NOT NULL UNIQUE CHECK (length(name_key) > 0),
  created_at TEXT NOT NULL
) STRICT;

CREATE TABLE bookmark_tags (
  bookmark_id INTEGER NOT NULL REFERENCES bookmarks(id) ON DELETE CASCADE,
  tag_id INTEGER NOT NULL REFERENCES tags(id) ON DELETE CASCADE,
  PRIMARY KEY (bookmark_id, tag_id)
) STRICT, WITHOUT ROWID;

CREATE INDEX bookmark_tags_tag_bookmark_idx ON bookmark_tags(tag_id, bookmark_id);

CREATE VIRTUAL TABLE bookmark_search USING fts5(
  title,
  address,
  description,
  note_plain,
  tokenize = 'trigram'
);

-- Backfill bookmarks created before this migration. Application writes replace
-- these values with NFKC/case-normalized content through SearchRepository.
INSERT INTO bookmark_search(rowid, title, address, description, note_plain)
SELECT id, title, address, description, note_plain FROM bookmarks;

-- Triggers preserve transactional row membership for every write path. The
-- repository performs the stronger Unicode normalization when it owns a write.
CREATE TRIGGER bookmark_search_after_insert
AFTER INSERT ON bookmarks
BEGIN
  INSERT INTO bookmark_search(rowid, title, address, description, note_plain)
  VALUES (new.id, new.title, new.address, new.description, new.note_plain);
END;

CREATE TRIGGER bookmark_search_after_update
AFTER UPDATE OF title, address, description, note_plain ON bookmarks
BEGIN
  DELETE FROM bookmark_search WHERE rowid = old.id;
  INSERT INTO bookmark_search(rowid, title, address, description, note_plain)
  VALUES (new.id, new.title, new.address, new.description, new.note_plain);
END;

CREATE TRIGGER bookmark_search_after_delete
AFTER DELETE ON bookmarks
BEGIN
  DELETE FROM bookmark_search WHERE rowid = old.id;
END;
import type { AppDatabase } from "../../src/server/db/database.js";
import {
  InvalidSearchCursorError,
  SearchRepository,
  type SearchRequest,
} from "../../src/server/repositories/search-repository.js";
import { compileSearchAst } from "../../src/server/services/search/search-compiler.js";
import { parseSearchQueryOrThrow } from "../../src/shared/search/parser.js";
import { withTestDatabase } from "../helpers/database.js";

const NOW = "2026-09-17T12:00:00.000Z";

interface SeedBookmark {
  id: number;
  title: string;
  address?: string;
  description?: string;
  note?: string;
  tags?: string[];
  favorite?: boolean;
  unread?: boolean;
  archived?: boolean;
  createdAt?: string;
  updatedAt?: string;
}

function nameKey(value: string): string {
  return value.normalize("NFKC").replace(/\s+/gu, " ").trim().toLocaleLowerCase("und");
}

function seed(database: AppDatabase, bookmark: SeedBookmark): void {
  const address = bookmark.address ?? `https://example.test/${bookmark.id}`;
  const titleKey = nameKey(bookmark.title);
  database
    .prepare(`
      INSERT INTO bookmarks (
        id, address, normalized_address, title, title_sort_key, title_provenance,
        description, description_provenance, metadata_status, note_markdown, note_plain,
        is_favorite, is_unread, archived_at, created_at, updated_at
      ) VALUES (?, ?, ?, ?, ?, 'user', ?, 'user', 'complete', '', ?, ?, ?, ?, ?, ?)
    `)
    .run(
      bookmark.id,
      address,
      address,
      bookmark.title,
      titleKey,
      bookmark.description ?? "",
      bookmark.note ?? "",
      bookmark.favorite ? 1 : 0,
      bookmark.unread ? 1 : 0,
      bookmark.archived ? NOW : null,
      bookmark.createdAt ?? NOW,
      bookmark.updatedAt ?? bookmark.createdAt ?? NOW,
    );

  for (const displayName of bookmark.tags ?? []) {
    const key = nameKey(displayName);
    database
      .prepare("INSERT OR IGNORE INTO tags(display_name, name_key, created_at) VALUES (?, ?, ?)")
      .run(displayName, key, NOW);
    database
      .prepare(`
        INSERT INTO bookmark_tags(bookmark_id, tag_id)
        SELECT ?, id FROM tags WHERE name_key = ?
      `)
      .run(bookmark.id, key);
  }
}

function request(overrides: Partial<SearchRequest> = {}): SearchRequest {
  return {
    scope: "active",
    query: "",
    tags: [],
    favorite: null,
    unread: null,
    sort: "created_desc",
    limit: 50,
    ...overrides,
  };
}

describe("search evaluator", () => {
  it("composes adjacent terms across different searchable fields", async () => {
    await withTestDatabase(({ database }) => {
      seed(database, { id: 1, title: "Alpha handbook", note: "Includes beta examples" });
      seed(database, { id: 2, title: "Alpha only" });
      const repository = new SearchRepository(database);

      expect(repository.search(request({ query: "alpha beta" })).items.map(({ id }) => id)).toEqual(
        [1],
      );
    });
  });

  it("keeps quoted phrases within one field and never spans fields", async () => {
    await withTestDatabase(({ database }) => {
      seed(database, { id: 1, title: "red green reference" });
      seed(database, { id: 2, title: "red", description: "green" });
      const repository = new SearchRepository(database);

      expect(
        repository.search(request({ query: '"red green"' })).items.map(({ id }) => id),
      ).toEqual([1]);
    });
  });

  it("matches ordinary tag substrings and exact relational #tag atoms", async () => {
    await withTestDatabase(({ database }) => {
      seed(database, { id: 1, title: "One", tags: ["Machine Learning"] });
      seed(database, { id: 2, title: "Two", tags: ["Machine"] });
      const repository = new SearchRepository(database);

      expect(repository.search(request({ query: "learn" })).items.map(({ id }) => id)).toEqual([1]);
      expect(
        repository.search(request({ query: '#"machine learning"' })).items.map(({ id }) => id),
      ).toEqual([1]);
      expect(repository.search(request({ query: "#machine" })).items.map(({ id }) => id)).toEqual([
        2,
      ]);
    });
  });

  it("uses a bounded scan for one/two-character atoms and normalizes Unicode", async () => {
    await withTestDatabase(({ database }) => {
      seed(database, { id: 1, title: "A UI guide" });
      seed(database, { id: 2, title: "Ａlpha ÉCOLE" });
      const repository = new SearchRepository(database);
      repository.synchronizeBookmark(2);

      expect(repository.search(request({ query: "ui" })).items.map(({ id }) => id)).toEqual([1]);
      expect(
        repository.search(request({ query: "alpha école" })).items.map(({ id }) => id),
      ).toEqual([2]);
    });
  });

  it("requires every selected tag and combines status filters", async () => {
    await withTestDatabase(({ database }) => {
      seed(database, {
        id: 1,
        title: "Matching",
        tags: ["News", "Research"],
        favorite: true,
        unread: true,
      });
      seed(database, { id: 2, title: "One tag", tags: ["News"], favorite: true, unread: true });
      seed(database, {
        id: 3,
        title: "Wrong status",
        tags: ["News", "Research"],
        favorite: false,
        unread: true,
      });
      const repository = new SearchRepository(database);

      const page = repository.search(
        request({ tags: [" NEWS ", "research"], favorite: true, unread: true }),
      );
      expect(page.items.map(({ id }) => id)).toEqual([1]);
      expect(page.items[0]?.tags.map(({ name }) => name)).toEqual(["News", "Research"]);
    });
  });

  it("applies active, Read Later, and archived scope rules without clearing unread state", async () => {
    await withTestDatabase(({ database }) => {
      seed(database, { id: 1, title: "Active read" });
      seed(database, { id: 2, title: "Active unread", unread: true });
      seed(database, { id: 3, title: "Archived unread", unread: true, archived: true });
      const repository = new SearchRepository(database);

      expect(repository.search(request({ scope: "active" })).items.map(({ id }) => id)).toEqual([
        2, 1,
      ]);
      expect(repository.search(request({ scope: "read_later" })).items.map(({ id }) => id)).toEqual(
        [2],
      );
      expect(repository.search(request({ scope: "archived" })).items.map(({ id }) => id)).toEqual([
        3,
      ]);
      expect(repository.search(request({ scope: "archived" })).items[0]?.unread).toBe(true);
    });
  });

  it.each([
    ["created_desc", [3, 2, 1]],
    ["created_asc", [1, 2, 3]],
    ["updated_desc", [3, 2, 1]],
    ["title_asc", [2, 1, 3]],
  ] as const)("uses deterministic id tie-breakers for %s", async (sort, ids) => {
    await withTestDatabase(({ database }) => {
      seed(database, { id: 1, title: "Bravo", createdAt: NOW, updatedAt: NOW });
      seed(database, { id: 2, title: "Alpha", createdAt: NOW, updatedAt: NOW });
      seed(database, { id: 3, title: "Bravo", createdAt: NOW, updatedAt: NOW });
      const repository = new SearchRepository(database);
      expect(repository.search(request({ sort })).items.map(({ id }) => id)).toEqual(ids);
    });
  });

  it("returns a total independent of pages and a stable validated cursor", async () => {
    await withTestDatabase(({ database }) => {
      for (let id = 1; id <= 5; id += 1) seed(database, { id, title: `Item ${id}` });
      const repository = new SearchRepository(database);
      const first = repository.search(request({ limit: 2 }));
      const second = repository.search(
        request({ limit: 2, cursor: first.nextCursor ?? undefined }),
      );
      const third = repository.search(
        request({ limit: 2, cursor: second.nextCursor ?? undefined }),
      );

      expect(first.total).toBe(5);
      expect(first.items.map(({ id }) => id)).toEqual([5, 4]);
      expect(second.items.map(({ id }) => id)).toEqual([3, 2]);
      expect(third.items.map(({ id }) => id)).toEqual([1]);
      expect(third.nextCursor).toBeNull();
      expect(() => repository.search(request({ cursor: "not-a-cursor" }))).toThrow(
        InvalidSearchCursorError,
      );
      expect(() =>
        repository.search(request({ sort: "title_asc", cursor: first.nextCursor ?? undefined })),
      ).toThrow(InvalidSearchCursorError);
    });
  });

  it("binds atom values instead of interpolating them into SQL", () => {
    const hostile = `x' UNION SELECT id FROM bookmarks --`;
    const compiled = compileSearchAst(parseSearchQueryOrThrow(`"${hostile}"`));
    expect(compiled.sql).not.toContain(hostile);
    expect(compiled.parameters).toContain(hostile.normalize("NFKC").toLocaleLowerCase("und"));
  });
});
