function StatefulControls({
  initial,
  onChange,
}: {
  initial: ViewState;
  onChange: (next: ViewState) => void;
}) {
  const [current, setCurrent] = useState(initial);
  return (
    <SearchControls
      view={current}
      tags={tags}
      total={12}
      onChange={(next) => {
        setCurrent(next);
        onChange(next);
      }}
